class PageUtil:
    def __init__(self, data, page_size):
        self._data = self._encapsulate_collection(data)
        self._page_size = page_size
        self._total_items = len(self._data)
        self._total_pages = self._calculate_total_pages(self._total_items, self._page_size)

    @property
    def data(self):
        return self._data().copy()

    @property
    def page_size(self):
        return self._page_size

    @property
    def total_items(self):
        return self._total_items

    @property
    def total_pages(self):
        return self._total_pages

    def get_page(self, page_number):
        if not self._is_valid_page_number(page_number):
            return []

        start_index = self._get_start_index(page_number)
        end_index = min(start_index + self._page_size, self._total_items)
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        if not self._is_valid_page_number(page_number):
            return {}

        start_index = self._get_start_index(page_number)
        end_index = min(start_index + self._page_size, self._total_items)
        page_data = self.data[start_index:end_index]

        return {
            "current_page": page_number,
            "per_page": self._page_size,
            "total_pages": self._total_pages,
            "total_items": self._total_items,
            "has_previous": self._has_previous_page(page_number),
            "has_next": self._has_next_page(page_number),
            "data": page_data
        }

    def search(self, keyword):
        results = self._filter_items_by_keyword(keyword)
        return self._build_search_info(keyword, results)

    def _encapsulate_collection(self, data):
        if isinstance(data, (list, tuple)):
            return lambda: list(data)
        else:
            original_data = list(data)
            return lambda: list(original_data)

    def _calculate_total_pages(self, total_items, page_size):
        if page_size <= 0:
            return 0
        return (total_items + page_size - 1) // page_size

    def _is_valid_page_number(self, page_number):
        return 1 <= page_number <= self._total_pages

    def _get_start_index(self, page_number):
        return (page_number - 1) * self._page_size

    def _has_previous_page(self, page_number):
        return page_number > 1

    def _has_next_page(self, page_number):
        return page_number < self._total_pages

    def _filter_items_by_keyword(self, keyword):
        return [item for item in self.data if keyword in str(item)]

    def _build_search_info(self, keyword, results):
        num_results = len(results)
        num_pages = self._calculate_total_pages(num_results, self._page_size)
        return {
            "keyword": keyword,
            "total_results": num_results,
            "total_pages": num_pages,
            "results": results
        }
